import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"The pull-request bar","description":"","frontmatter":{},"headers":[],"relativePath":"dev/pr-workflow.md","filePath":"dev/pr-workflow.md"}'),s={name:"dev/pr-workflow.md"};function i(n,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="the-pull-request-bar" tabindex="-1">The pull-request bar <a class="header-anchor" href="#the-pull-request-bar" aria-label="Permalink to &quot;The pull-request bar&quot;">​</a></h1><p>What a PR must clear, in order:</p><ol><li><strong>Builds clean</strong>: <code>make kernel</code> with <code>-Wall -Wextra -Werror</code> - on your machine <em>and</em> on CI (CI&#39;s toolchain is often stricter; the multiboot2 packed-cast and rdrand setc fixes exist precisely because a stricter GCC/GAS on the runner caught what local builds accepted).</li><li><strong>Host tests</strong>: <code>make test</code> - zero failures.</li><li><strong>Boots</strong>: <code>make run-bios</code> and <code>make run-uefi</code> - both reach the <code>oc&gt;</code> prompt with <code>boot complete ... OK</code>.</li><li><strong>The deep test for whatever you touched</strong> - the matrix in <a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a> (storage -&gt; fstest; crypto -&gt; cryptotest + HTTPS E2E; watchdog/klog/health -&gt; the WP-12 E2E; boot path -&gt; the 28-check regression).</li><li><strong>Reproducible</strong>: <code>make reproducible-check</code> prints PASS.</li><li><strong>Docs in the same PR</strong>: new command -&gt; its reference page is generated (<code>make api-docs</code> refreshes <code>docs/manual/commands/</code> and <code>INTERFACES.md</code>); new interface -&gt; the surface tables; behaviour change -&gt; the matching manual page.</li><li><strong>CI green</strong>: the workflow runs build, ISO, packages, host tests and the reproducibility gate on every PR - merge only on green.</li></ol><h2 id="writing-the-pr-description" tabindex="-1">Writing the PR description <a class="header-anchor" href="#writing-the-pr-description" aria-label="Permalink to &quot;Writing the PR description&quot;">​</a></h2><ul><li>What changed and <em>why</em> - the commit messages carry the detail.</li><li>Which tests you ran (commands + result lines, pasted).</li><li>Anything you deliberately did NOT do (scope edges).</li></ul><h2 id="review-expectations" tabindex="-1">Review expectations <a class="header-anchor" href="#review-expectations" aria-label="Permalink to &quot;Review expectations&quot;">​</a></h2><p>Expect questions about error paths, DMA bounds, and what happens when the hardware lies (a truncated table, a stuck NAK, a card that answers garbage). The tree&#39;s own history - BUG-0136..0238 - is a catalogue of exactly these; reading a few of those fix commits is the best preparation.</p>',7)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
